const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

// In-page helper for the brain view screenshots: fakes a Go crazy run on a goal with N agents.
// window.__brain(n, phase): phase 'mid' | 'checking' | 'met' | 'blocked' | 'stopped' | 'grow'
const st = window.__ensemble
const s0 = st.getState()
const chatId = s0.chatId
const lead = (s0.chats.find((c) => c.id === chatId) || {}).leadId || s0.settings.leadId || s0.accounts.find((a) => a.enabled).id
const U = (window.__u = { chatId, lead, chat: null, agents: [], tasks: [], items: {} })

// id, name, parent, role
const L = lead
const ALL = [
  ['r1', 'Research lead', L, 'Leads the research'],
  ['b1', 'Build lead', L, 'Leads the builders'],
  ['c1', 'Critique lead', L, 'Runs the critics'],
  ['v1', 'Verification lead', L, 'Checks every claim and test'],
  ['m1', 'Memory keeper', L, 'Keeps the board current'],
  ['s1', 'Scout 1', 'r1', 'Pricing of five rivals'],
  ['ba', 'Builder A', 'b1', 'Version A of the page'],
  ['k1', 'Critic 1', 'c1', 'Attacks the copy'],
  ['t1', 'Tester 1', 'v1', 'Runs the checkout tests'],
  ['s2', 'Scout 2', 'r1', 'Checkout patterns'],
  ['s3', 'Scout 3', 'r1', 'Payment provider docs'],
  ['bb', 'Builder B', 'b1', 'Version B of the page'],
  ['bc', 'Builder C', 'b1', 'Version C of the page'],
  ['ka', 'Critic A', 'ba', 'Critique: version A'],
  ['ta', 'Tester A', 'ba', 'Test: version A'],
  ['f1', 'Fact-checker 1', 's1', 'Checks the rival prices'],
  ['vf', 'Verifier', 'v1', 'Verify: round 2'],
  ['ar', 'Archivist', 'm1', 'Files findings on the board'],
  ['s4', 'Scout 4', 'r1', 'Accessibility rules'],
  ['k2', 'Critic 2', 'c1', 'Attacks the layout'],
  ['qa', 'Source check A', 'ka', 'Checks the critique sources'],
  ['ca', 'Citation check', 'qa', 'Opens every cited link'],
  ['s5', 'Scout 5', 'r1', 'Tax and VAT'],
  ['kb', 'Critic B', 'bb', 'Critique: version B'],
  ['s6', 'Scout 6', 'r1', 'Annual discounts'],
  ['s7', 'Scout 7', 'r1', 'Conversion studies'],
  ['s8', 'Scout 8', 'r1', 'Refund policies'],
  ['bd', 'Builder D', 'b1', 'Version D of the page'],
  ['k3', 'Critic 3', 'c1', 'Reads it cold'],
  ['k4', 'Critic 4', 'c1', 'Checks it against the brief'],
  ['t2', 'Tester 2', 'v1', 'Runs it on a phone'],
  ['t3', 'Tester 3', 'v1', 'Runs it with a screen reader'],
  ['f2', 'Fact-checker 2', 's3', 'Checks the provider limits'],
  ['kc', 'Critic C', 'bc', 'Critique: version C'],
  ['tb', 'Tester B', 'bb', 'Test: version B'],
  ['rt', 'Red team 1', 'k1', 'Tries to break the claims'],
  ['rp', 'Replay tester', 't1', 'Replays the failing case'],
  ['q1', 'Source check 1', 'f1', 'Checks the sources'],
  ['sr', 'Screen reader test', 'ta', 'Reads it aloud'],
  ['lc', 'Link check', 'q1', 'Opens every link'],
  ['s9', 'Scout 9', 'r1', 'Trial lengths'],
  ['s10', 'Scout 10', 'r1', 'Plan naming'],
  ['be', 'Builder E', 'b1', 'Version E of the page'],
  ['kd', 'Critic D', 'bd', 'Critique: version D'],
  ['tc', 'Tester C', 'bc', 'Test: version C'],
  ['nt', 'Note-taker', 'm1', 'Writes down decisions'],
  ['f3', 'Fact-checker 3', 's5', 'Checks the VAT rates'],
]
const ACTS = {
  Scout: 'Searching the web for annual plan discounts',
  Builder: 'Writing designs/b/index.html',
  Critic: 'Comparing version B with the rubric',
  Tester: 'Running the checkout tests',
  'Fact-checker': 'Opening stripe.com/pricing',
  Verifier: 'Re-running every test from a clean checkout',
  'Source check': 'Reading the cited study',
  'Citation check': 'Opening 14 cited links',
  'Link check': 'Opening every link on the page',
  'Memory keeper': 'Updating the rubric on the board',
  Archivist: 'Filing findings on the board',
  'Note-taker': 'Writing down the decision on pricing tiers',
  'Red team': 'Trying to break the refund claim',
  'Replay tester': 'Replaying the empty cart case',
  'Screen reader test': 'Reading the page with a screen reader',
  'Research lead': 'Merging what the scouts found',
  'Build lead': 'Waiting on the builders',
  'Critique lead': 'Ranking the critiques',
  'Verification lead': 'Waiting on the testers',
}
const base = (n) => n.replace(/\s+(\d+|[A-Z])$/, '')
const accents = ['teal', 'blue', 'violet', 'clay', 'amber', 'rose', 'green', 'slate']

// Who is working mid-run, deterministically.
function statusOf(id, name, phase, i) {
  if (phase === 'met' || phase === 'stopped') return 'done'
  const b = base(name)
  if (b === 'Scout') return i % 3 === 0 ? 'running' : 'done'
  if (['Research lead', 'Build lead', 'Verification lead', 'Critique lead'].includes(b)) return 'hold'
  if (b === 'Builder') return 'hold'
  if (b === 'Tester' || b === 'Verifier') return i % 2 ? 'queued' : 'running'
  if (b === 'Archivist') return 'done'
  return 'running'
}

window.__brain = (n, phase) => {
  const now = Date.now()
  const list = ALL.slice(0, n - 1)
  const have = new Set(list.map((x) => x[0]).concat([L]))
  const depthOf = (id) => {
    let d = 0
    let cur = id
    while (cur !== L) {
      d++
      cur = ALL.find((x) => x[0] === cur)[2]
    }
    return d
  }
  const holdsFor = new Set(list.map((x) => x[2]))
  U.agents = list.map(([id, name, by, role], i) => ({
    id,
    name,
    provider: i % 3 === 1 ? 'chatgpt' : 'claude',
    accent: accents[i % accents.length],
    enabled: true,
    role,
    model: null,
    effort: null,
    createdAt: now - 200000,
    spawned: { chatId, base: lead, by, depth: depthOf(id), at: now - 200000 + i * 900, gone: (phase === 'met' && depthOf(id) >= 2) || undefined },
  }))
  const states = {}
  U.tasks = list.map(([id, name, by, role], i) => {
    let s = statusOf(id, name, phase, i)
    if (s === 'hold' && !holdsFor.has(id)) s = 'running'
    if (phase === 'checking' && s === 'running') s = i % 2 ? 'done' : s
    if (phase === 'blocked' && s === 'running') s = i % 3 ? 'done' : s
    const t = { id: 'ft-' + id, chatId, title: role, brief: role, from: by, to: id, status: s === 'hold' ? 'running' : s, holding: s === 'hold' || undefined, createdAt: now - 150000 + i * 900, startedAt: now - 120000, finishedAt: s === 'done' ? now - 20000 : undefined, result: s === 'done' ? 'Done. Findings are on the board.' : undefined }
    if (s === 'running') states[chatId + ':' + id] = { chatId, accountId: id, phase: i % 4 === 0 ? 'tool' : 'thinking', activity: ACTS[base(name)] || ACTS[name] || 'Working', queued: 0, turnStartedAt: now - 30000 + i * 500 }
    return t
  })
  // Work handed across regions: the critique lead hands version B's critique to Builder B's critic; the verifier waits on the builders.
  if (have.has('kb') && phase !== 'met') U.tasks.push({ id: 'ft-x1', chatId, title: 'Critique: version B, second pass', brief: '', from: 'c1', to: 'kb', status: 'running', createdAt: now - 9000, startedAt: now - 8000 })
  if (have.has('vf')) {
    const vt = U.tasks.find((t) => t.id === 'ft-vf')
    vt.after = ['ft-ba', 'ft-bb'].filter((x) => U.tasks.some((t) => t.id === x))
    vt.waitingFor = 'Builder A and Builder B'
  }
  if (have.has('ar') && have.has('s3')) U.tasks.push({ id: 'ft-x2', chatId, title: 'File: provider limits', brief: '', from: 's3', to: 'ar', status: phase === 'met' ? 'done' : 'running', createdAt: now - 7000 })
  // Lateral messages: a critic writes to a builder directly; a scout to the memory keeper.
  U.items = {}
  if (have.has('k1') && have.has('ba')) U.items[chatId + ':ba'] = [{ id: 'pm1', ts: now - 6000, kind: 'peer', from: 'k1', tag: 'message', text: 'The hero headline promises a free trial the page never mentions again.' }]
  if (have.has('s2') && have.has('m1')) U.items[chatId + ':m1'] = [{ id: 'pm2', ts: now - 4000, kind: 'peer', from: 's2', tag: 'message', text: 'Four of five rivals show the annual price first.' }]
  if (phase === 'met') for (const k of Object.keys(states)) delete states[k]
  if (phase !== 'met' && phase !== 'stopped') states[chatId + ':' + lead] = phase === 'checking' ? undefined : { chatId, accountId: lead, phase: 'thinking', activity: 'Planning round 2', queued: 0, turnStartedAt: now - 20000 }
  const log = [{ round: 0, ts: now - 90000, met: false, note: 'The checkout test fails on an empty cart, and the hero copy scores 6 of 10 on clarity.' }]
  if (phase === 'met') log.push({ round: 1, ts: now - 1000, met: true, note: 'Every check passed: the tests are green, the page opens, and it scores 8.6 of 10 on the rubric.' })
  const goal = {
    id: 'g-brain',
    text: 'Ship a pricing page that converts, with a working checkout',
    doneWhen: 'the tests pass, the page was opened, and it scores 8 or more on the rubric',
    status: phase === 'met' ? 'met' : phase === 'blocked' ? 'blocked' : phase === 'stopped' ? 'stopped' : 'active',
    round: phase === 'stopped' ? 5 : 1,
    maxRounds: 6,
    check: 'fresh',
    createdAt: now - 214000,
    endedAt: phase === 'met' || phase === 'stopped' ? now - 500 : undefined,
    note: phase === 'met' ? log[1].note : phase === 'blocked' ? 'Which payment provider should the checkout use? The brief allows Stripe or Paddle.' : log[0].note,
    log,
    checking: phase === 'checking' || undefined,
    mode: 'gocrazy',
  }
  U.chat = { ultra: true, crazy: phase !== 'met' && phase !== 'stopped', goal }
  U.states = states
  // The lead charted the rubric scores over rounds.
  const rounds = phase === 'met' ? [6.1, 7.4, 8.6] : [6.1, 7.4]
  const chartText = 'Round ' + rounds.length + ' is scored.\n\n```ui\n' + JSON.stringify({ type: 'chart', kind: 'line', title: 'Rubric score by round', x: rounds.map((_, i) => 'Round ' + (i + 1)), series: [{ name: 'Overall', data: rounds }, { name: 'Clarity', data: rounds.map((v) => +(v - 0.9).toFixed(1)) }] }) + '\n```\n'
  U.items[chatId + ':' + lead] = [{ id: 'chart-1', ts: now - 3000, kind: 'assistant', text: chartText }]
  apply(true)
  return n + ' agents, ' + phase
}

// A big team, generated: five regions, a chain in Building eight levels deep, the rest grown by a
// fixed pseudo-random walk so every run draws the same team.
window.__brainBig = (n, phase) => {
  let seed = 7
  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647
  const heads = [['r1', 'Research lead'], ['b1', 'Build lead'], ['c1', 'Critique lead'], ['v1', 'Verification lead'], ['m1', 'Memory keeper']]
  const kids = { Scout: 'Fact-checker', Builder: 'Critic', Critic: 'Source check', Tester: 'Replay tester', Archivist: 'Note-taker', 'Fact-checker': 'Source check', 'Source check': 'Link check', 'Replay tester': 'Replay tester', 'Note-taker': 'Note-taker', 'Link check': 'Link check' }
  const list = heads.map(([id, name]) => [id, name, L, name])
  const depth = { [L]: 0, r1: 1, b1: 1, c1: 1, v1: 1, m1: 1 }
  const kind = { r1: 'Scout', b1: 'Builder', c1: 'Critic', v1: 'Tester', m1: 'Archivist' }
  const regionOf = { r1: 'r1', b1: 'b1', c1: 'c1', v1: 'v1', m1: 'm1' }
  const count = {}
  const add = (parent, k) => {
    count[k] = (count[k] || 0) + 1
    const id = 'x' + list.length
    list.push([id, k + ' ' + count[k], parent, k === 'Builder' ? 'Version ' + count[k] + ' of the page' : k + ' work'])
    depth[id] = depth[parent] + 1
    kind[id] = kids[k] || k
    regionOf[id] = regionOf[parent]
    return id
  }
  // The deep chain: Build lead > Builder > Critic > Source check > Link check ... down to level 8.
  let p = 'b1'
  for (let d = 2; d <= 8 && list.length < n - 1; d++) p = add(p, kind[p])
  const weights = [0.3, 0.26, 0.18, 0.14, 0.12]
  while (list.length < n - 1) {
    let r = rnd()
    let h = 0
    for (; h < 4 && r > weights[h]; h++) r -= weights[h]
    const region = heads[h][0]
    const pool = list.filter(([id]) => regionOf[id] === region && depth[id] < 8)
    const pick = pool[Math.floor(Math.pow(rnd(), 1.6) * pool.length)][0]
    add(pick, kind[pick])
  }
  const now = Date.now()
  const parents = new Set(list.map((x) => x[2]))
  U.agents = list.map(([id, name, by, role], i) => ({ id, name, provider: i % 3 === 1 ? 'chatgpt' : 'claude', accent: accents[i % accents.length], enabled: true, role, model: null, effort: null, createdAt: now - 300000, spawned: { chatId, base: lead, by, depth: depth[id], at: now - 300000 + i * 400, gone: (phase === 'met' && depth[id] >= 2) || undefined } }))
  const states = {}
  U.tasks = list.map(([id, name, by, role], i) => {
    const r = (i * 37) % 10
    const st = phase === 'met' ? 'done' : parents.has(id) ? 'hold' : r < 4 ? 'running' : r < 8 ? 'done' : 'queued'
    if (st === 'running') states[chatId + ':' + id] = { chatId, accountId: id, phase: 'thinking', activity: ACTS[base(name)] || 'Working', queued: 0, turnStartedAt: now - 20000 + i * 100 }
    return { id: 'ft-' + id, chatId, title: role, brief: role, from: by, to: id, status: st === 'hold' ? 'running' : st, holding: st === 'hold' || undefined, createdAt: now - 200000 + i * 400, startedAt: now - 150000, finishedAt: st === 'done' ? now - 10000 : undefined }
  })
  const b2 = list.find((x) => x[1] === 'Builder 2')
  if (b2) U.tasks.push({ id: 'ft-x1', chatId, title: 'Critique: version 2, second pass', brief: '', from: 'c1', to: b2[0], status: phase === 'met' ? 'done' : 'running', createdAt: now - 9000 })
  U.items = {}
  U.items[chatId + ':m1'] = [{ id: 'pm2', ts: now - 4000, kind: 'peer', from: 'r1', tag: 'message', text: 'Four of five rivals show the annual price first.' }]
  if (phase !== 'met') states[chatId + ':' + lead] = { chatId, accountId: lead, phase: 'thinking', activity: 'Planning round 3', queued: 0, turnStartedAt: now - 20000 }
  const log = [
    { round: 0, ts: now - 200000, met: false, note: 'Version 2 leads at 39 of 50; the pricing table and the mobile layout score lowest.' },
    { round: 1, ts: now - 90000, met: false, note: 'Version 2 is at 43 of 50; the mobile layout still scores lowest.' },
  ]
  if (phase === 'met') log.push({ round: 2, ts: now - 1000, met: true, note: 'Both judging rounds score version 2 at 46 of 50, and every test passes.' })
  const goal = { id: 'g-big', text: 'Design the landing page, and keep going until the judges score it 45 of 50', doneWhen: 'both judging rounds score the winner 45 of 50 or more', status: phase === 'met' ? 'met' : 'active', round: 2, maxRounds: 8, check: 'fresh', createdAt: now - 400000, endedAt: phase === 'met' ? now - 500 : undefined, note: log[log.length - 1].note, log, mode: 'gocrazy' }
  U.chat = { ultra: true, crazy: phase !== 'met', goal }
  U.states = states
  const rounds = phase === 'met' ? [39, 43, 46] : [39, 43]
  U.items[chatId + ':' + lead] = [{ id: 'chart-1', ts: now - 3000, kind: 'assistant', text: 'Scores so far.\n\n```ui\n' + JSON.stringify({ type: 'chart', kind: 'line', title: 'Rubric score by round', x: rounds.map((_, i) => 'Round ' + (i + 1)), series: [{ name: 'Winner', data: rounds }] }) + '\n```\n' }]
  apply(true)
  return n + ' agents (big), deepest level ' + Math.max(...Object.values(depth)) + ', ' + phase
}

function apply(force) {
  st.setState((s) => {
    const out = {}
    out.chats = s.chats.map((c) => {
      if (c.id !== chatId) return c
      const ids = new Set(U.agents.map((a) => a.id))
      return { ...c, ...U.chat, agents: U.agents }
    })
    out.members = { ...s.members, ...Object.fromEntries(U.agents.map((a) => [a.id, a])) }
    out.tasks = { ...s.tasks, [chatId]: U.tasks }
    const agents = { ...s.agents }
    for (const k of Object.keys(agents)) if (k.startsWith(chatId + ':')) delete agents[k]
    for (const [k, v] of Object.entries(U.states || {})) if (v) agents[k] = v
    out.agents = agents
    const items = { ...s.items }
    for (const [k, v] of Object.entries(U.items)) {
      const cur = (items[k] || []).filter((x) => !v.some((y) => y.id === x.id))
      items[k] = [...cur, ...v]
    }
    out.items = items
    return out
  })
}
U.apply = apply
st.subscribe((s) => {
  const c = s.chats.find((c) => c.id === chatId)
  if (!c || !U.chat) return
  if (c.crazy !== U.chat.crazy || c.goal !== U.chat.goal || c.ultra !== true || U.agents.some((a) => !(c.agents || []).some((x) => x === a))) setTimeout(() => apply(), 0)
})
return 'brain fake ready on ' + chatId

const t0 = performance.now(); let n = 0; let worst = 0; let last = t0;
await new Promise(r => { const f = (t) => { n++; worst = Math.max(worst, t - last); last = t; if (t - t0 < 2000) requestAnimationFrame(f); else r(); }; requestAnimationFrame(f); });
return 'fps ' + Math.round(n / ((performance.now() - t0) / 1000)) + ', worst frame ' + Math.round(worst) + ' ms, nodes ' + document.querySelectorAll('[data-brain-view] .nn-node').length;
